/** @deprecated Use the pulled `catalog.aiProviders.<provider>.models.<model>` token instead — see {@link AiProviderConnector}. */
export function aiProviderConnector(opts) {
    return {
        id: opts.id,
        ...(opts.name != null && { name: opts.name }),
        ...(opts.model != null && { model: opts.model }),
    };
}
